static const char *const manual_parts[] = { manual_0, manual_1 };

#define MANUAL_PARTS (sizeof manual_parts / sizeof manual_parts[0])

/* ------------------------------------------------------------------ main -- */

static unsigned long parse_size(const char *s)
{
    char *e;
    errno = 0;
    unsigned long v = strtoul(s, &e, 10);
    if (errno || e == s) fatal("bad size: %s", s);
    if (*e == 'k' || *e == 'K') { v *= 1024UL; e++; }
    else if (*e == 'm' || *e == 'M') { v *= 1024UL * 1024UL; e++; }
    else if (*e == 'g' || *e == 'G') { v *= 1024UL * 1024UL * 1024UL; e++; }
    if (*e) fatal("bad size: %s", s);
    return v;
}

int main(int argc, char **argv)
{
    const char *config = NULL;
    int no_defaults = 0, list_only = 0;
    int i, end_opts = 0;

    for (i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (!end_opts && !strcmp(a, "--")) { end_opts = 1; continue; }
        if (end_opts || a[0] != '-' || a[1] == '\0') break;

        if (!strcmp(a, "-h") || !strcmp(a, "--usage")) {
            fputs(usage_text, stdout);
            return 0;
        }
        if (!strcmp(a, "--help") || !strcmp(a, "--manual")) {
            for (size_t k = 0; k < MANUAL_PARTS; k++)
                fputs(manual_parts[k], stdout);
            return 0;
        }
        if (!strcmp(a, "--version")) { printf("%s %s\n", PROG, VERSION); return 0; }
        if (!strcmp(a, "-v") || !strcmp(a, "--verbose")) { opt_verbose = 1; continue; }
        if (!strcmp(a, "-q") || !strcmp(a, "--quiet")) { opt_quiet = 1; continue; }
        if (!strcmp(a, "-i") || !strcmp(a, "--in-place")) { opt_inplace = 1; continue; }
        if (!strcmp(a, "-n") || !strcmp(a, "--dry-run")) { opt_dryrun = 1; continue; }
        if (!strcmp(a, "-r") || !strcmp(a, "--report")) { opt_report = 1; continue; }
        if (!strcmp(a, "-l") || !strcmp(a, "--list")) { list_only = 1; continue; }
        if (!strcmp(a, "-k") || !strcmp(a, "--keep")) { opt_keep = 1; continue; }
        if (!strcmp(a, "-s") || !strcmp(a, "--strict")) { opt_strict = 1; continue; }
        if (!strcmp(a, "-B") || !strcmp(a, "--allow-binary")) { opt_allow_binary = 1; continue; }
        if (!strcmp(a, "--no-defaults")) { no_defaults = 1; continue; }

        if (!strcmp(a, "-c") || !strcmp(a, "--config")) {
            if (++i >= argc) fatal("%s requires a file", a);
            config = argv[i];
            continue;
        }
        if (!strcmp(a, "-o") || !strcmp(a, "--output")) {
            if (++i >= argc) fatal("%s requires a file", a);
            opt_output = argv[i];
            continue;
        }
        if (!strcmp(a, "-m") || !strcmp(a, "--marker")) {
            if (++i >= argc) fatal("%s requires a string", a);
            marker = argv[i];
            marker_len = strlen(marker);
            continue;
        }
        if (!strcmp(a, "-M") || !strcmp(a, "--max-size")) {
            if (++i >= argc) fatal("%s requires a size", a);
            opt_max_size = parse_size(argv[i]);
            continue;
        }
        fatal("unknown option: %s (try -h)", a);
    }

    if (opt_inplace && opt_output) fatal("-i and -o are mutually exclusive");
    if (opt_output && argc - i > 1) fatal("-o takes exactly one input file");

    Table t;
    table_init(&t, TRANSLIT_TABLE_N + 256);
    if (!no_defaults) table_load_defaults(&t);
    config_discover(&t, config);
    if (t.multi_n > 1) qsort(t.multi, t.multi_n, sizeof *t.multi, multi_cmp);

    if (list_only) { table_list(&t); return 0; }

    if (i >= argc)
        fatal("no input files (standard input is not read; try -h)");

    int status = EX_OK;
    Stats total = {0, 0, 0, 0, 0};

    for (; i < argc; i++) {
        const char *path = argv[i];
        unsigned char *in = NULL;
        size_t len = 0;
        mode_t mode = 0644;

        if (slurp(path, &in, &len, &mode) != 0) {
            if (status == EX_OK) status = EX_USAGE;
            continue;
        }

        Buf out;
        buf_init(&out, len + len / 8 + 64);
        Stats st = {0, 0, 0, 0, 0};
        convert(&t, in, len, &out, &st);
        st.bytes_in = len;
        st.bytes_out = out.n;
        free(in);

        if (!opt_dryrun && !opt_report) {
            int rc;
            if (opt_inplace) rc = write_atomic(path, out.p, out.n, mode);
            else if (opt_output) rc = write_out(opt_output, out.p, out.n, 0644);
            else rc = write_stdout(out.p, out.n);
            if (rc != 0) status = EX_USAGE;
        }
        free(out.p);

        total.bytes_in += st.bytes_in;
        total.bytes_out += st.bytes_out;
        total.replaced += st.replaced;
        total.unmapped += st.unmapped;
        total.invalid += st.invalid;

        if (opt_verbose)
            warnx_("%s: %zu -> %zu bytes, %zu replaced, %zu unmapped, "
                   "%zu invalid", path, st.bytes_in, st.bytes_out,
                   st.replaced, st.unmapped, st.invalid);
    }

    if (opt_report) census_print();

    if (!opt_quiet && !opt_verbose && !opt_report &&
        (total.unmapped || total.invalid))
        warnx_("%zu unmapped, %zu invalid (--report lists them)",
               total.unmapped, total.invalid);

    if (opt_strict && (total.unmapped || total.invalid) && status == EX_OK)
        status = EX_UNMAPPED;

    return status;
}
